import subprocess
def run(chunk):
    import subprocess as sp
    p=sp.run(["./executable","-e",chunk], capture_output=True, text=True, timeout=5)
    return p.stdout.strip()
for lib in ["bit", "jit", "jit.opt", "debug", "package", "os", "coroutine", "io"]:
    chunk = f"local t=require('{lib}'); local ok, v=pcall(function() return require('{lib}') end); print('---{lib}'); for k,v in pairs(require('{lib}')) do if type(v)=='function' then print(k, tostring(v)) else print(k, type(v), tostring(v):sub(1,40)) end end" if lib not in ["jit.opt"] else f"for k,v in pairs(jit.opt) do print(k, type(v), tostring(v)) end"
    # simpler:
    if lib=="jit.opt":
        out=run("for k,v in pairs(jit.opt) do print(k, tostring(v)) end")
    elif lib=="jit":
        out=run("for k,v in pairs(jit) do if type(v)=='function' then print(k, tostring(v)) else print(k, type(v), tostring(v)) end end")
    elif lib=="bit":
        out=run("for k,v in pairs(bit) do print(k, tostring(v)) end")
    elif lib=="debug":
        out=run("for k,v in pairs(debug) do print(k, tostring(v)) end")
    elif lib=="package":
        out=run("for k,v in pairs(package) do if type(v)=='function' then print(k, tostring(v)) else print(k, type(v)) end end")
    else:
        out=run(f"for k,v in pairs({lib}) do if type(v)=='function' then print(k, tostring(v)) else print(k, type(v)) end end")
    print(f"=== {lib} ===")
    print(out)
PY
"}

