# ---- Lua value system ----
class LuaError(Exception):
    def __init__(self, msg):
        super().__init__(msg)
        self.msg = msg

class LuaNilType:
    def __repr__(self): return "nil"
    def __str__(self): return "nil"
NIL = LuaNilType()

def is_falsy(v):
    return v is NIL or v is False

def is_truthy(v):
    return not is_falsy(v)

def lua_type(v):
    if v is NIL: return "nil"
    if v is True or v is False: return "boolean"
    if isinstance(v, (int, float)): return "number"
    if isinstance(v, str): return "string"
    if isinstance(v, LuaTable): return "table"
    if isinstance(v, (LuaFunction, LuaBuiltin)): return "function"
    if isinstance(v, LuaThread): return "thread"
    if isinstance(v, LuaUserdata): return "userdata"
    if isinstance(v, LuaCData): return "cdata"
    return "userdata"

# Number formatting like LuaJIT %.14g
def format_number(n):
    if isinstance(n, bool):
        return "true" if n else "false"
    if isinstance(n, int) and not isinstance(n, bool):
        # Lua numbers are doubles; but integers print without decimal
        return str(n)
    # n is float
    if math.isnan(n):
        return "nan"
    if math.isinf(n):
        return "inf" if n > 0 else "-inf"
    # Check if integral and within 2^31? Lua prints integers without decimal?
    # Use %.14g
    s = "%.14g" % n
    # Python's %.14g may give slightly different for large? Should match C.
    # Handle -0?
    if s == "-0":
        s = "-0"
    return s

def lua_tostring(v):
    if v is NIL: return "nil"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v, str): return v
    if isinstance(v, float):
        return format_number(v)
    if isinstance(v, int) and not isinstance(v, bool):
        return str(v)
    if isinstance(v, LuaTable):
        return f"table: 0x{id(v):012x}"[-18:]
        # Actually format as table: 0x... with 12 hex digits? We'll use id
    if isinstance(v, (LuaFunction, LuaBuiltin)):
        return tostring_func(v)
    if isinstance(v, LuaThread):
        return f"thread: 0x{id(v):012x}"
    if isinstance(v, LuaUserdata):
        if v.is_file:
            return f"file (0x{id(v):012x})"
        return f"userdata: 0x{id(v):012x}"
    if isinstance(v, LuaCData):
        return f"cdata<{v.ctype}>: 0x{id(v):012x}"
    return str(v)

def tostring_func(f):
    if isinstance(f, LuaBuiltin):
        return f"function: builtin#{f.builtin_id}"
    else:
        return f"function: 0x{id(f):012x}"

# tonumber with base
def lua_tonumber(v, base=None):
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        if base is not None:
            raise LuaError("bad argument #2 to 'tonumber' (number expected, got number)")  # actually check?
        return float(v) if isinstance(v, float) else float(v)
    if isinstance(v, str):
        s = v.strip()
        if base is None:
            # auto: try decimal, hex?
            if s == "": return NIL
            # hex?
            try:
                if s.lower().startswith("0x"):
                    return float(int(s, 16))
                # Try float
                # Lua allows trailing? Must be entire string? e.g., tonumber("10x") -> nil
                # Use regex?
                if re.match(r'^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$', s):
                    return float(s)
                else:
                    return NIL
            except:
                return NIL
        else:
            # base given: must be 2..36? Check
            if not isinstance(base, (int, float)):
                raise LuaError("bad argument #2 to 'tonumber' (number expected, got string)")
            b = int(base)
            if b < 2 or b > 36:
                raise LuaError("bad argument #2 to 'tonumber' (base out of range)")
            s2 = s.strip()
            # Remove leading +/-
            try:
                # Lua tonumber with base only handles integers? e.g., tonumber("ff",16)=255
                # Allow?
                return float(int(s2, b))
            except:
                return NIL
    return NIL

PYEOF
