class LuaTable:
    def __init__(self):
        self.dict = {}
        self.metatable = None
        # For array part optimization not needed
    def rawget(self, k):
        # k could be NIL? Actually rawget with nil key errors?
        hk = lua_hash_key(k)
        return self.dict.get(hk, NIL)
    def rawset(self, k, v):
        hk = lua_hash_key(k)
        if v is NIL:
            self.dict.pop(hk, None)
        else:
            self.dict[hk] = (k, v)
    def keys(self):
        return [k for (k,v) in self.dict.values()]
    def items(self):
        return [(k,v) for (k,v) in self.dict.values()]

def lua_hash_key(k):
    if isinstance(k, float) and k.is_integer():
        # normalize int/float keys? 1 and 1.0 same
        return ('n', int(k))
