    return []

def builtin_debug_gethook(args, env, fenv):
    return [NIL, NIL, 0]

def builtin_debug_debug(args, env, fenv):
    # Enters debug prompt? For our purposes, do nothing.
    return []

def builtin_debug_traceback(args, env, fenv):
    # traceback([thread,] [message [, level]])? Returns string with traceback.
    # Our earlier test xpcall with debug.traceback gave traceback with [C] etc.
    # For simplicity, if called with message, return message + "\n" + traceback?
    msg=None; level=1
    idx=0
    # Check if first arg is thread?
    if len(args)>=1 and isinstance(args[0], LuaThread):
        idx=1
    if len(args)>idx:
        v=args[idx]
        if isinstance(v, str):
            msg=v
        elif v is NIL:
            msg=None
        else:
            msg=lua_tostring(v)
    # level?
    # Return msg + traceback?
    tb=format_traceback()
    if msg is None:
        return [tb]
    else:
        return [f"{msg}\n{tb}"]

