    # Placeholder: always fail? Return nil + msg?
    return [NIL, "loadlib not supported"]

def builtin_package_searchpath(args, env, fenv):
    # searchpath(name, path [, sep [, rep]])? Returns filename or nil+msg?
    # Implement: search package.path for file?
    if len(args)<2:
        raise LuaError("bad argument #2 to 'searchpath' (string expected, got no value)")
    name=str_arg(args,1,'searchpath')
    path=str_arg(args,2,'searchpath')
    sep="."
    rep="/"
    if len(args)>=3 and args[2] is not NIL:
        sep=str_arg(args,3,'searchpath')
    if len(args)>=4 and args[3] is not NIL:
        rep=str_arg(args,4,'searchpath')
    fname=name.replace(sep, rep)
    for tmpl in path.split(";"):
        if tmpl=="":
            continue
        f=tmpl.replace("?", fname)
        if os.path.isfile(f):
            return [f]
    return [NIL, f"\n\tno file '{path}'"]

# ---- JIT library ----
def builtin_jit_on(args, env, fenv):
    global jit_on
    # jit.on([func [, ...]])? With no args, turn on globally. With func, turn on for func? For simplicity, just set global on.
    # If args contain function, need to handle? For CLI -j on with no args, just on.
    # For jit.on(func) with function, also on? We'll just set on.
    jit_on=True
    return []

def builtin_jit_off(args, env, fenv):
    global jit_on
    jit_on=False
    return []

def builtin_jit_flush(args, env, fenv):
    # Flush cache (no-op)
    return []

def builtin_jit_status(args, env, fenv):
    return [jit_status_string()]

def builtin_jit_security(args, env, fenv):
    if len(args)<1:
        raise LuaError("bad argument #1 to '?' (string expected, got no value)")
    v=args[0]
    if not isinstance(v, str):
        raise LuaError(f"bad argument #1 to '?' (string expected, got {lua_type(v)})")
    # Valid options? Original: security("on") gave invalid option 'on'? Wait earlier security("on") gave invalid option 'on'? Actually we tested security('on') and got invalid option 'on'. So what are valid? Maybe no valid? Let's check docs: jit.security? Possibly takes no args? Hmm.
    # For now, any string gives invalid option.
    raise LuaError(f"bad argument #1 to '?' (invalid option '{v}')")

def builtin_jit_attach(args, env, fenv):
    if len(args)<1:
        raise LuaError("bad argument #1 to '?' (function expected, got no value)")
    v=args[0]
    if not isinstance(v, (LuaFunction, LuaBuiltin)):
        raise LuaError(f"bad argument #1 to '?' (function expected, got {lua_type(v)})")
    # Additional args? Second arg is event string? e.g., attach(print,'bc') succeeded. So accept any.
    return []

def builtin_jit_opt_start(args, env, fenv):
    if len(args)<1:
        return []
    s=args[0]
    if s is NIL:
        raise LuaError("bad argument #1 to '?' (string expected, got nil)")
    if not isinstance(s, str):
        # Original with number 123 gave "unknown ... '123'" (converted to string). So convert.
        s=lua_tostring(s)
    # Call jit_opt_start which may raise LuaError with appropriate message
    jit_opt_start(s)
    return []

