        if not isinstance(ctype, str):
            raise LuaError(f"bad argument #1 to 'cast' (string expected, got {lua_type(ctype)})")
        return [LuaCData(ctype, val)]
    t.rawset("cast", LuaBuiltin(ffi_cast, "ffi.cast", 189))
    def ffi_typeof(args, env, fenv):
        if len(args)<1:
            raise LuaError("bad argument #1 to 'typeof' (string expected, got no value)")
        return [LuaCData("ctype", args[0])]
    t.rawset("typeof", LuaBuiltin(ffi_typeof, "ffi.typeof", 190))
    def ffi_typeinfo(args, env, fenv):
        return [0]
    t.rawset("typeinfo", LuaBuiltin(ffi_typeinfo, "ffi.typeinfo", 191))
