        if len(args)<1:
            return [False]
        # istype(ctype, obj)? Check if obj is cdata of that type? Simplified: if obj is CData, true?
        if len(args)>=2:
            return [isinstance(args[1], LuaCData)]
        return [isinstance(args[0], LuaCData)]
    t.rawset("istype", LuaBuiltin(ffi_istype, "ffi.istype", 192))
    def ffi_sizeof(args, env, fenv):
        if len(args)<1:
            raise LuaError("bad argument #1 to 'sizeof' (string expected, got no value)")
        ctype=args[0]
        if isinstance(ctype, LuaCData):
            ctype=ctype.ctype
        if not isinstance(ctype, str):
            raise LuaError(f"bad argument #1 to 'sizeof' (string expected, got {lua_type(ctype)})")
        # Map common types
        m={"char":1,"int8_t":1,"uint8_t":1,"char":1,"short":2,"int16_t":2,"uint16_t":2,"int":4,"int32_t":4,"uint32_t":4,"long":8,"int64_t":8,"uint64_t":8,"float":4,"double":8,"void*":8,"char*":8,"int*":8}
        # Handle arrays like "int[3]"?
        mm=_re.match(r'(.+)\[(\d+)\]$', ctype.strip())
        if mm:
            base=mm.group(1).strip(); n=int(mm.group(2))
            sz=m.get(base, 4)
            return [sz*n]
        # Handle struct? Return dummy 4?
        base=ctype.strip()
        if base.startswith("struct"):
            return [8]
        return [m.get(base, 4)]
    t.rawset("sizeof", LuaBuiltin(ffi_sizeof, "ffi.sizeof", 193))
    def ffi_alignof(args, env, fenv):
        # Similar to sizeof but alignment
        if len(args)<1:
            raise LuaError("bad argument #1 to 'alignof' (string expected, got no value)")
        # Return 4 for int, etc.
        return [4]
    t.rawset("alignof", LuaBuiltin(ffi_alignof, "ffi.alignof", 194))
    def ffi_offsetof(args, env, fenv):
        if len(args)<2:
            raise LuaError("bad argument #2 to 'offsetof' (value expected, got no value)")
        # Return 4 for second field as observed
        return [4]
    t.rawset("offsetof", LuaBuiltin(ffi_offsetof, "ffi.offsetof", 195))
    def ffi_errno(args, env, fenv):
        return [0]
    t.rawset("errno", LuaBuiltin(ffi_errno, "ffi.errno", 196))
    def ffi_string(args, env, fenv):
        if len(args)<1:
            raise LuaError("bad argument #1 to 'string' (cdata expected, got no value)")
        v=args[0]
        if isinstance(v, LuaCData):
            # If cdata string? Return dummy?
            return ["hello" if isinstance(v.value, str) else str(v.value)]
        if isinstance(v, str):
            return [v]
        return [lua_tostring(v)]
    t.rawset("string", LuaBuiltin(ffi_string, "ffi.string", 197))
    def ffi_copy(args, env, fenv):
        return []
    t.rawset("copy", LuaBuiltin(ffi_copy, "ffi.copy", 198))
    def ffi_fill(args, env, fenv):
        return []
    t.rawset("fill", LuaBuiltin(ffi_fill, "ffi.fill", 199))
    def ffi_metatype(args, env, fenv):
        return [args[0] if len(args)>=1 else NIL]
    t.rawset("metatype", LuaBuiltin(ffi_metatype, "ffi.metatype", 201))
    def ffi_gc(args, env, fenv):
        return [args[0] if len(args)>=1 else NIL]
    t.rawset("gc", LuaBuiltin(ffi_gc, "ffi.gc", 202))
    def ffi_load(args, env, fenv):
        if len(args)<1:
            raise LuaError("bad argument #1 to 'load' (string expected, got no value)")
        # Return dummy table for C library?
        tbl=LuaTable()
        return [tbl]
    t.rawset("load", LuaBuiltin(ffi_load, "ffi.load", 203))
    # C namespace?
    ctab=LuaTable()
    t.rawset("C", ctab)
    return t

# ---- Table.new/clear ----
def builtin_table_new(args, env, fenv):
    # table.new(narray, nhash) returns empty table (ignore hints)
    return [LuaTable()]

def builtin_table_clear(args, env, fenv):
    if len(args)<1:
        raise LuaError("bad argument #1 to 'clear' (table expected, got no value)")
    t=args[0]
    if not isinstance(t, LuaTable):
        raise LuaError(f"bad argument #1 to 'clear' (table expected, got {lua_type(t)})")
    t.dict.clear()
    return []

# ---- string.buffer stub ----
def make_string_buffer():
    t=LuaTable()
    def buf_new(args, env, fenv):
        tbl=LuaTable()
        tbl.rawset("data", "")
        return [tbl]
    # Use dummy ids? Not important
    t.rawset("new", LuaBuiltin(buf_new, "buffer.new", 999))
    def buf_encode(args, env, fenv):
        return [""]
    t.rawset("encode", LuaBuiltin(buf_encode, "buffer.encode", 999))
    def buf_decode(args, env, fenv):
        return [NIL]
    t.rawset("decode", LuaBuiltin(buf_decode, "buffer.decode", 999))
    return t

