import subprocess, re
def run(path, args, stdin=None, env_extra=None):
    import subprocess as sp, os
    env=dict(os.environ)
    if env_extra:
        for k,v in env_extra.items():
            if v is None:
                env.pop(k,None)
            else:
                env[k]=v
    p=sp.run([path]+args, input=stdin, capture_output=True, text=True, env=env, timeout=5)
    return p.stdout, p.stderr, p.returncode
def norm_prog(s, prog):
    return s.replace(prog, "PROG")
def norm_addr(s):
    return re.sub(r'0x[0-9a-fA-F]+', '0xADDR', s)
def compare(args, stdin=None, env_extra=None):
    o=run("./executable", args, stdin, env_extra)
    n=run("./new_exe_test", args, stdin, env_extra)
    # Normalize prog names and addresses
    o_norm=(norm_addr(norm_prog(o[0],"./executable")), norm_addr(norm_prog(o[1],"./executable")), o[2])
    n_norm=(norm_addr(norm_prog(n[0],"./new_exe_test")), norm_addr(norm_prog(n[1],"./new_exe_test")), n[2])
    # Also need to normalize arg table prog? Already via norm_prog (since stdout contains prog)
    match=o_norm==n_norm
    print(f"{args} stdin={stdin!r} match:{match}")
    if not match:
        print(" orig:", o)
        print(" new :", n)
        print(" onorm:", o_norm)
        print(" nnorm:", n_norm)
    return match

# Test many CLI cases
for a in [["-h"], ["-v"], ["-E"], ["-O1"], ["-j","off"], ["-b","foo"], ["-bl"], ["-j","v","-e","print(1)"], ["-Ofoo","-e","print(1)"], ["-e"], ["-l"], ["-j"], ["- Ev"], ["-v","-e","print(1)"], ["-e",'print(1)',"-v"]]:
    compare(a)
for a,stdin in [([], "print(42)\n"), (["-"], "print(99)\n"), (["-i"], "print(1)\n"), (["-e",'print(1)',"-i"], "print(2)\n")]:
    compare(a, stdin)
